$ErrorActionPreference = 'Stop'
try {
  $adapters = @(NetAdapter\Get-NetAdapter -Physical | Microsoft.PowerShell.Core\Where-Object { $_.Status -eq 'Up' -or $_.Status -eq 'Disconnected' })
  if ($adapters.Count -eq 0) { 'No Wi-Fi or Ethernet adapter that is switched on was found, so there is nothing to restart.'; exit 0 }
  $wasUp = @()
  foreach ($adapter in $adapters) { if ($adapter.Status -eq 'Up') { $wasUp += $adapter.Name } }
  $failed = 0
  foreach ($adapter in $adapters) {
    'Restarting ' + $adapter.Name
    try { NetAdapter\Restart-NetAdapter -Name $adapter.Name -Confirm:$false } catch { $failed++; 'Could not restart ' + $adapter.Name + ': ' + $_.Exception.Message }
  }
  $limit = [DateTime]::UtcNow.AddSeconds(30)
  do {
    $waiting = @()
    foreach ($name in $wasUp) { if ((NetAdapter\Get-NetAdapter -Name $name).Status -ne 'Up') { $waiting += $name } }
    if ($waiting.Count -gt 0) { Microsoft.PowerShell.Utility\Start-Sleep -Seconds 2 }
  } while ($waiting.Count -gt 0 -and [DateTime]::UtcNow -lt $limit)
  if ($waiting.Count -gt 0) { ($waiting -join ', ') + ' did not reconnect within 30 seconds.'; exit 1 }
  if ($failed -gt 0) { exit 1 }
  if ($wasUp.Count -gt 0) { ($wasUp -join ', ') + ' reconnected.' }
} catch { 'Could not restart the network adapters: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $limit = [DateTime]::UtcNow.AddSeconds(25)
  do {
    $lines = @(); $bad = @()
    $up = @(NetAdapter\Get-NetAdapter -Physical | Microsoft.PowerShell.Core\Where-Object { $_.Status -eq 'Up' })
    foreach ($adapter in $up) {
      $config = NetTCPIP\Get-NetIPConfiguration -InterfaceIndex $adapter.ifIndex
      $real = @(); $routers = @()
      foreach ($address in $config.IPv4Address) { if (-not $address.IPAddress.StartsWith('169.254.')) { $real += $address.IPAddress } }
      foreach ($gateway in $config.IPv4DefaultGateway) { $routers += $gateway.NextHop }
      if ($real.Count -gt 0) {
        $line = $adapter.Name + ': address ' + ($real -join ', ')
        if ($routers.Count -gt 0) { $line += ', router ' + ($routers -join ', ') } else { $line += ', no router listed' }
        $lines += $line
      } else { $bad += $adapter.Name }
    }
    if (($up.Count -eq 0 -or $bad.Count -gt 0) -and [DateTime]::UtcNow -lt $limit) { Microsoft.PowerShell.Utility\Start-Sleep -Seconds 2 }
  } while (($up.Count -eq 0 -or $bad.Count -gt 0) -and [DateTime]::UtcNow -lt $limit)
  $lines
  if ($up.Count -eq 0) { 'No Wi-Fi or Ethernet adapter is connected.'; exit 1 }
  if ($bad.Count -gt 0) { ($bad -join ', ') + ' only has a self-assigned 169.254 address, which means the router did not answer. Check that the router is on and that this PC is joined to the right network, then try again.'; exit 1 }
  'The router answered.'
} catch { 'Could not check the address: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $changed = 0
  foreach ($network in @(NetConnection\Get-NetConnectionProfile)) {
    if ($network.NetworkCategory -eq 'Public') {
      NetConnection\Set-NetConnectionProfile -InterfaceIndex $network.InterfaceIndex -NetworkCategory Private
      $network.Name + ' is now a Private network.'
      $changed++
    }
  }
  if ($changed -eq 0) { 'No connected network was set to Public, so nothing was changed.' }
} catch { 'Could not change the network type: ' + $_.Exception.Message; exit 1 }

$ErrorActionPreference = 'Stop'
try {
  $changed = 0
  foreach ($name in 'fdPHost', 'FDResPub', 'SSDPSRV', 'upnphost') {
    $service = Microsoft.PowerShell.Management\Get-Service -Name $name -ErrorAction SilentlyContinue
    if ($service -and $service.StartType -eq 'Disabled') {
      Microsoft.PowerShell.Management\Set-Service -Name $name -StartupType Manual
      $service.DisplayName + ' was turned off. It is now set to Manual, which is how Windows ships it.'
      $changed++
    }
  }
  if ($changed -eq 0) { 'None of these services was turned off.' }
} catch { 'Could not turn the services on: ' + $_.Exception.Message; exit 1 }

$ErrorActionPreference = 'Stop'
try {
  $networks = @(NetConnection\Get-NetConnectionProfile)
  if ($networks.Count -eq 0) { 'Windows does not list a connected network.'; exit 1 }
  $public = 0; $private = 0
  foreach ($network in $networks) {
    $network.Name + ' (' + $network.InterfaceAlias + '): ' + $network.NetworkCategory
    if ($network.NetworkCategory -eq 'Public') { $public++ }
    if ($network.NetworkCategory -eq 'Private') { $private++ }
  }
  $problem = $false
  if ($public -gt 0) {
    'A Public network is treated as untrusted: Windows hides this PC on it and does not look for other PCs. For a home or office network choose Private under Settings > Network and internet > Wi-Fi or Ethernet > the network > Network profile type, or tick the option for that on this page.'
    $problem = $true
  }
  if ($private -gt 0) {
    $rules = @(NetSecurity\Get-NetFirewallRule -Group '@FirewallAPI.dll,-32752' -Direction Inbound -Enabled True -ErrorAction SilentlyContinue)
    $forPrivate = 0
    foreach ($rule in $rules) { if ($rule.Profile.ToString() -match 'Private|Any') { $forPrivate++ } }
    if ($forPrivate -eq 0) {
      'Windows Firewall has Network discovery turned off for Private networks, so other PCs cannot see this one. Turn on Network discovery in Settings > Network and internet > Advanced network settings > Advanced sharing settings. This fix does not change firewall rules.'
      $problem = $true
    } else { 'Windows Firewall allows network discovery on Private networks.' }
  }
  if ($problem) { exit 1 }
} catch { 'Could not check the network type: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $stopped = 0
  foreach ($name in 'Dnscache', 'fdPHost', 'FDResPub', 'SSDPSRV', 'upnphost') {
    $service = Microsoft.PowerShell.Management\Get-Service -Name $name -ErrorAction SilentlyContinue
    if (-not $service) { $name + ' is not on this PC.'; continue }
    $service.DisplayName + ': ' + $service.Status + ' (startup ' + $service.StartType + ')'
    if ($service.Status -ne 'Running' -and ($name -eq 'Dnscache' -or $name -eq 'fdPHost' -or $name -eq 'FDResPub')) { $stopped++ }
  }
  if ($stopped -gt 0) { 'A service that network discovery needs is not running.'; exit 1 }
  'The services network discovery needs are running.'
} catch { 'Could not check the services: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $settings = Microsoft.PowerShell.Management\Get-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Internet Settings'
  if ($settings.ProxyEnable -eq 1) { 'Use a proxy server: on' } else { 'Use a proxy server: off' }
  if ($settings.ProxyServer) { 'Proxy address: ' + $settings.ProxyServer } else { 'Proxy address: none' }
  if ($settings.AutoConfigURL) { 'Setup script address: ' + $settings.AutoConfigURL } else { 'Setup script address: none' }
  foreach ($variable in 'HTTP_PROXY', 'HTTPS_PROXY', 'ALL_PROXY') {
    $value = [Environment]::GetEnvironmentVariable($variable)
    if ($value) { $variable + ' is set to ' + $value + '. Programs such as git, npm and pip use it; this fix does not change it. Remove it under Environment Variables in System Properties if it is not yours.' }
  }
} catch { 'Could not read the proxy settings: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $address = [uri]'http://www.msftconnecttest.com/connecttest.txt'
  $proxy = [System.Net.WebRequest]::GetSystemWebProxy().GetProxy($address)
  if ($proxy.AbsoluteUri -eq $address.AbsoluteUri) { 'Apps that use the Windows proxy settings now connect directly.' }
  else { 'Apps still reach the internet through ' + $proxy.AbsoluteUri + '. Something else sets this proxy: a work or school policy, or the program that put it there.'; exit 1 }
} catch { 'Could not check the proxy: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $limit = [DateTime]::UtcNow.AddSeconds(40)
  do {
    $networks = @(NetConnection\Get-NetConnectionProfile)
    $online = 0
    foreach ($network in $networks) { if ($network.IPv4Connectivity -eq 'Internet' -or $network.IPv6Connectivity -eq 'Internet') { $online++ } }
    if ($online -eq 0 -and [DateTime]::UtcNow -lt $limit) { Microsoft.PowerShell.Utility\Start-Sleep -Seconds 2 }
  } while ($online -eq 0 -and [DateTime]::UtcNow -lt $limit)
  foreach ($network in $networks) { $network.Name + ' (' + $network.InterfaceAlias + '): IPv4 ' + $network.IPv4Connectivity + ', IPv6 ' + $network.IPv6Connectivity }
  if ($networks.Count -eq 0) { 'Windows does not list a connected network yet. If Wi-Fi is switched on, give it a moment and look at the network icon again.'; exit 1 }
  if ($online -eq 0) { 'Windows still reports no internet. If a website opens in your browser, the problem is the proxy or a VPN rather than the connection: try the fix for a stuck proxy.'; exit 1 }
  'Windows reports that this PC is online.'
} catch { 'Could not check the connection: ' + $_.Exception.Message; exit 2 }

$ErrorActionPreference = 'Stop'
try {
  $connections = @(SmbShare\Get-SmbMapping)
  if ($connections.Count -eq 0) { 'No network folders or drives are connected right now, so there is nothing to disconnect.'; exit 0 }
  $failed = 0
  foreach ($connection in $connections) {
    $remote = $connection.RemotePath
    try {
      if ($connection.LocalPath) {
        SmbShare\Remove-SmbMapping -LocalPath $connection.LocalPath -Force -ErrorAction Stop
        'Disconnected ' + $connection.LocalPath + ' (' + $remote + ').'
      } else {
        SmbShare\Remove-SmbMapping -RemotePath $remote -Force -ErrorAction Stop
        'Disconnected ' + $remote + '.'
      }
    } catch { $failed++; 'Could not disconnect ' + $remote + ': ' + $_.Exception.Message }
  }
  if ($failed -gt 0) { exit 1 }
  'Mapped drives are only disconnected, not forgotten: Windows connects them again the next time you open them or sign in.'
} catch { 'Could not list the network connections: ' + $_.Exception.Message; exit 2 }
